def read(f):return json.loads((E/f).read_text())
def p95(a):return sorted(a)[math.ceil(len(a)*.95)-1]
def ci(pairs):
 if not pairs:return [None,None]
 values=sorted(statistics.mean(rng.choices(pairs,k=len(pairs))) for _ in range(2000));return [values[49],values[1949]]
rows=read('paired-attempts.json');tasks=read('paired-message-tasks.json');offline=read('offline-metrics.json');real=read('realization-attempts.json');summary={'seed':2026,'bootstrap_samples':2000,'exclusions':0,'tile_feedback':[],'message_tasks':[],'realization':[],'offline':[]}
md=['# Automated paired metrics','', 'Software replays only; no AAC-user study, task-cue timing or measured audible onset. All attempted scenarios remain in each denominator. Timeouts/invalid text/missing audio count as failures.','', '## Visible tile feedback','', '| Locale | Before successes / attempts | After successes / attempts | Before p95 ms | After p95 ms | Paired mean change ms (95% bootstrap interval) |','|---|---:|---:|---:|---:|---|']
